import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.security.SecurityRequirement;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.servlet.http.HttpServletRequest;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.GrantedAuthority;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.HashMap;
import java.util.Map;

@RestController
@RequestMapping("/mock")
@RequiredArgsConstructor
@SecurityRequirement(name = "bearer-jwt")
@Tag(name = "Mock Responses", description = "Dynamic mock endpoint responses")
public class MockResponseController {

    private final MockEndpointRepository endpointRepository;

    @RequestMapping("/**")
    @Operation(summary = "Mock response", description = "Returns configured mock response for the path")
    public ResponseEntity<?> handleMockRequest(HttpServletRequest request, Authentication authentication) {
        String path = request.getRequestURI().replace("/mock", "");
        String method = request.getMethod();

        MockEndpoint endpoint = endpointRepository.findByPathAndMethod(path, method)
                .orElse(null);

        if (endpoint == null) {
            Map<String, String> error = new HashMap<>();
            error.put("error", "Mock endpoint not found");
            error.put("path", path);
            error.put("method", method);
            return ResponseEntity.status(HttpStatus.NOT_FOUND).body(error);
        }

        if (endpoint.getRequiredRole() != null && !endpoint.getRequiredRole().isEmpty()) {
            boolean hasRole = authentication.getAuthorities().stream()
                    .map(GrantedAuthority::getAuthority)
                    .anyMatch(role -> role.equals("ROLE_" + endpoint.getRequiredRole()));

            if (!hasRole) {
                throw new AccessDeniedException("Insufficient permissions");
            }
        }

        if (endpoint.getDelayMs() > 0) {
            try {
                Thread.sleep(endpoint.getDelayMs());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        MediaType contentType = MediaType.parseMediaType(endpoint.getContentType());

        return ResponseEntity
                .status(endpoint.getStatusCode())
                .contentType(contentType)
                .body(endpoint.getResponse());
    }
}

