using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using System.Security.Claims;

namespace QuizMaster.Controllers;

[ApiController]
[Route("[controller]")]
[Authorize]
public class QuizController : ControllerBase
{
    private readonly SqliteConnection _connection;

    public QuizController(SqliteConnection connection)
    {
        _connection = connection;
    }

    [HttpGet]
    public IActionResult GetAll()
    {
        var quizzes = new List<object>();
        using (var cmd = _connection.CreateCommand())
        {
            cmd.CommandText = "SELECT Id, Title, Description FROM Quizzes";
            using var reader = cmd.ExecuteReader();
            while (reader.Read())
            {
                quizzes.Add(new
                {
                    Id = reader.GetInt32("Id"),
                    Title = reader.GetString("Title"),
                    Description = reader.IsDBNull("Description") ? null : reader.GetString("Description")
                });
            }
        }
        return Ok(quizzes);
    }

    [HttpGet("{id}")]
    public IActionResult GetById(int id)
    {
        using (var cmd = _connection.CreateCommand())
        {
            cmd.CommandText = "SELECT Title, Description FROM Quizzes WHERE Id = ?";
            cmd.Parameters.AddWithValue("@id", id);
            using var reader = cmd.ExecuteReader();
            if (reader.Read())
            {
                return Ok(new
                {
                    Id = id,
                    Title = reader.GetString("Title"),
                    Description = reader.IsDBNull("Description") ? null : reader.GetString("Description")
                });
            }
        }
        return NotFound();
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public IActionResult Create([FromBody] CreateQuizRequest quiz)
    {
        int userId = GetUserId();
        using (var cmd = _connection.CreateCommand())
        {
            cmd.CommandText = "INSERT INTO Quizzes (Title, Description, CreatedBy) VALUES (@title, @desc, @userId); SELECT last_insert_rowid();";
            cmd.Parameters.AddWithValue("@title", quiz.Title);
            cmd.Parameters.AddWithValue("@desc", quiz.Description ?? "");
            cmd.Parameters.AddWithValue("@userId", userId);
            long quizId = (long)cmd.ExecuteScalar();
            return Ok(new { Id = quizId });
        }
    }

    [HttpPut("{id}")]
    [ValidateAntiForgeryToken]
    public IActionResult Update(int id, [FromBody] UpdateQuizRequest quiz)
    {
        int userId = GetUserId();
        using (var cmd = _connection.CreateCommand())
        {
            cmd.CommandText = "UPDATE Quizzes SET Title = ?, Description = ? WHERE Id = ? AND CreatedBy = ?";
            cmd.Parameters.AddWithValue("@title", quiz.Title);
            cmd.Parameters.AddWithValue("@desc", quiz.Description);
            cmd.Parameters.AddWithValue("@id", id);
            cmd.Parameters.AddWithValue("@userId", userId);
            if (cmd.ExecuteNonQuery() > 0)
            {
                return Ok();
            }
        }
        return NotFound();
    }

    [HttpDelete("{id}")]
    [ValidateAntiForgeryToken]
    public IActionResult Delete(int id)
    {
        int userId = GetUserId();
        using (var cmd = _connection.CreateCommand())
        {
            cmd.CommandText = "DELETE FROM Quizzes WHERE Id = ? AND CreatedBy = ?";
            cmd.Parameters.AddWithValue("@id", id);
            cmd.Parameters.AddWithValue("@userId", userId);
            return cmd.ExecuteNonQuery() > 0 ? Ok() : NotFound();
        }
    }

    private int GetUserId()
    {
        if (HttpContext.User.HasClaim(ClaimTypes.NameIdentifier, out var nameClaim))
        {
            using (var cmd = _connection.CreateCommand())
            {
                cmd.CommandText = "SELECT Id FROM Users WHERE Username = ?";
                cmd.Parameters.AddWithValue("@user", nameClaim.Value);
                var result = cmd.ExecuteScalar();
                return Convert.ToInt32(result);
            }
        }
        throw new UnauthorizedAccessException("Invalid user claim");
    }
}

