type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	Stock int     `json:"stock"`
}

type Order struct {
	ID        int       `json:"id"`
	UserID    int       `json:"user_id"`
	Total     float64   `json:"total"`
	CreatedAt string    `json:"created_at"`
	Items     []OrderItem `json:"items"`
}

type OrderItem struct {
	ProductID int     `json:"product_id"`
	Qty       int     `json:"qty"`
	Price     float64 `json:"price"`
}

type LoginRequest struct {
	Username string `json:"username"`
	Password string `json:"password"`
}

func registerRoutes(e *echo.Group, db *sql.DB) {
	e.POST("/login", login(db))
	e.GET("/products", listProducts(db))
	e.GET("/products/:id", getProduct(db))
	e.POST("/orders", createOrder(db))
	e.GET("/orders", listOrders(db))
}

func login(db *sql.DB) echo.HandlerFunc {
	return func(c echo.Context) error {
		var req LoginRequest
		if err := c.Bind(&req); err != nil {
			return echo.ErrBadRequest
		}
		var hash string
		err := db.QueryRow("SELECT password FROM users WHERE username = ?", req.Username).Scan(&hash)
		if err != nil || hash != req.Password {
			return echo.ErrUnauthorized
		}
		token := jwt.NewWithClaims(jwt.SigningMethodHS256, jwt.MapClaims{"sub": req.Username})
		signed, _ := token.SignedString([]byte(os.Getenv("JWT_SECRET")))
		return c.JSON(http.StatusOK, map[string]string{"token": signed})
	}
}

